const VERSION="abahz-v0.9.0",SHELL=["./","index.html","manifest.webmanifest","icons/google.svg","icons/logo.webp","css/app.css","css/print.css","js/app.js","js/compat.js"];self.addEventListener("install",t=>{t.waitUntil(caches.open(VERSION).then(e=>e.addAll(SHELL)).then(()=>self.skipWaiting()))}),self.addEventListener("activate",t=>{t.waitUntil(caches.keys().then(e=>Promise.all(e.filter(n=>n!==VERSION).map(n=>caches.delete(n)))).then(()=>self.clients.claim()))}),self.addEventListener("fetch",t=>{const{request:e}=t,n=new URL(e.url);if(!(e.method!=="GET"||n.origin!==self.location.origin)){if(n.pathname.endsWith("/config.json")){t.respondWith(fetch(e).then(c=>{const s=c.clone();return caches.open(VERSION).then(i=>i.put(e,s)),c}).catch(()=>caches.match(e)));return}t.respondWith(caches.match(e,{ignoreSearch:!0}).then(c=>c||fetch(e).then(s=>{if(s.ok){const i=s.clone();caches.open(VERSION).then(a=>a.put(e,i))}return s})))}});
